    {"q": "Who received the 2020 Nobel Prize in Chemistry for CRISPR-Cas9?", "o": ["Watson and Crick", "Charpentier and Doudna", "Mojica and Zhang", "Sanger and Mullis"], "a": 1, "x": "Emmanuelle Charpentier and Jennifer Doudna showed in 2012 that it could be programmed to cut DNA.", "tema": "biotec"},
    {"q": "For which conditions was the first CRISPR-based treatment authorised in 2023?", "o": ["Alzheimer's and Parkinson's", "Sickle cell disease and beta-thalassaemia", "Type 2 diabetes", "Breast cancer"], "a": 1, "x": "It edits blood stem cells to reactivate fetal haemoglobin.", "tema": "biotec"},
    {"q": "What distinguishes germline editing from somatic editing?", "o": ["Germline editing is cheaper", "Germline changes are passed on to descendants", "Somatic editing is only done in plants", "There is no difference"], "a": 1, "x": "That is why the Oviedo Convention prohibits introducing modifications into the genome of descendants.", "tema": "biotec"},
    {"q": "What is a vector in gene therapy?", "o": ["A type of cancer", "A vehicle, usually a modified virus, that carries the gene into cells", "An oral medicine", "A diagnostic test"], "a": 1, "x": "The most used are adeno-associated viruses (AAV) and lentiviruses.", "tema": "biotec"},
    {"q": "Why is codeine not recommended in children under 12?", "o": ["Because it has no effect", "Because some children, ultrarapid CYP2D6 metabolisers, produce too much morphine", "Because it always causes allergy", "Because it is expensive"], "a": 1, "x": "It is a classic example of pharmacogenetics.", "tema": "biotec"},
